-- EVT hook file for chara_bank_menu (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft cr_partner_lock (partner_lock_bank_hooks.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Character Reforged › partner locks in the player bank (graft cr_partner_lock; docs/game/ui/partner-lock-bank.md).
-- A card used as the partner of another card's pair (Character Reforged's CMND_CHARACTERREFORGED_PARTNER_LOCKS: the
-- systems the active mods declare, e.g. All Miximaxed's Mix-Max, All Changed's mode change) in the bank screens:
--   * chara_bank_menu («Banco» of the team dock): his card is greyed and disabled (IsBankCharaEnabled false: Aceptar
--     plays the error sound, no COMANDOS, no pick for a formation slot), «Añadir a espacio vacío» finds no slot; the
--     real lock is Character Reforged's filter on the game's place commands (drags, the mouse, every team screen);
--   * both banks (chara_bank_menu, chara_bank_menu_for_search): the system's plate over his card (layer
--     cr_partner_badge, content\menus\partner_badge.toml: the plate's sprite and word come from the system);
--   * both banks: the corner badge (P.PaintCorner): the card's own «in a team» icon (the mesh _icon_teamdock01) shown with
--     a badge sprite and given back to the retail sprite when the instance shows another card. A card also in a team
--     wears the system's `status_badge_in_team` (the badge with the retail icon's mark). The player bank shows it on
--     every card with a pair of a system or a mix slot move of a system's aura type (P.SystemBadge); the «Crear …» bank
--     chooses its own (graft character_reforged_board, B.PaintBadge).
-- The lock list is asked once per open (again from Step when the answer was not ready, then the list is redrawn). HOOK file (graft [[hooks]], shipped
-- as is): VRFW_Host handlers; definitions only at chunk load (no engine call). Both stems' handlers are registered in
-- each VM: only the stem this VM hosts runs them.
do
  CharacterReforged_PartnerLock = CharacterReforged_PartnerLock or {}
  local P = CharacterReforged_PartnerLock
  P.ID = "CharacterReforged.partner_lock"
  P.LOCKS = 2231785866                               -- CMND_CHARACTERREFORGED_PARTNER_LOCKS () -> { { card, base, sprite, textId, text } }
  P.LOG = 3661580131                                 -- CMND_EVT_LOG
  P.TEXT_GET = 4074371074                            -- CMND_TEXT_GET (text id)
  P.CARD = 1791816279                                -- team00_01_chara_card_for_list (the bank's list cards)
  P.BADGE = 3251618956                               -- cr_partner_badge (the plate layer)
  P.BADGE_TEXT = 4030979030                          -- _text_plate01
  P.BADGE_SHEET = 4208557384                         -- #/menu/102_team/team11/team11_05/team11_05.g4tx
  P.BADGE_SLOT = 1514509020                          -- kizuna_base01 (the plate quad's sprite slot)
  P.SPRITE_SWAP = 558735651                          -- (layer, sheet, sprite, slot, 0, instance)
  P.SET_TEXT = 1083631230                            -- CMND_SET_MENU_TEXT_STRING (layer, node, text, instance)
  P.TEXT_VISIBLE = 1505208242                        -- CMND_SET_MENU_TEXT_VISIBLE (layer, node, on, instance)
  P.LAYER_VISIBLE = 711242136                        -- CMND_SET_LAYER_VISIBLE (layer, instance, on)
  P.QUICK_RETIRE_MODE = 5                            -- the bank's multi-select «Retiro rápido» mode (n18)
  P.USES = 286810102                                 -- CMND_CHARACTERREFORGED_PARTNER_USES () -> { { card, statusSprite,
                                                     -- order, isPartner, system, inTeamSprite } }
  P.MIX_BADGE = 2510484024                         -- CMND_CHARACTERREFORGED_MIX_BADGE (card) -> statusSprite, inTeamSprite
  P.CORNER_MESH = 430313174                          -- _icon_teamdock01 (mesh of the bank card)
  P.CORNER_SHEET = 4225297828                        -- #/menu/102_team/team00/team00_01/<LG>/team00_01.g4tx
  P.CORNER_SLOT = 1685973306                         -- icon_teamdock01 (the mesh's sprite slot = the retail sprite)
  P.MESH_VISIBLE = 3405944500                        -- CMND_SET_MESH_VISIBLE (layer, mesh, on, instance)
  P.STEMS = {"chara_bank_menu", "chara_bank_menu_for_search"}

  function P.Reset()
    P.map, P.logged, P.missed = nil, {}, false
    P.uses, P.uses_missed = nil, false               -- card -> { badge, team_badge, partner, system } (nil = not read yet)
    P.badges = {}                                    -- card -> { badge, team_badge } (P.SystemBadge)
    P.cornered, P.corner_logged = {}, {}             -- list instance wears a badge sprite; card's badge is in the log
  end
  P.Reset()

  function P.Log(...)
    pcall(funcLuaCommand, P.LOG, "partner_lock", ...)
  end

  -- card -> { base, sprite, textId, text }; nil while Character Reforged did not answer (asked again next time)
  function P.Map()
    if P.map ~= nil then
      return P.map
    end
    local ok, list = pcall(funcLuaCommand, P.LOCKS)
    if not ok or type(list) ~= "table" then
      P.missed = true
      return nil
    end
    local map, n = {}, 0
    for _, e in pairs(list) do
      if type(e) == "table" and type(e[1]) == "number" and e[1] ~= 0 then
        map[e[1]] = {base = e[2] or 0, sprite = e[3] or 0, text_id = e[4] or 0, text = e[5]}
        n = n + 1
      end
    end
    P.map = map
    P.Log("locks", n)
    return map
  end

  function P.Of(card)
    if type(card) ~= "number" or card == 0 then
      return nil
    end
    local map = P.Map()
    return map ~= nil and map[card] or nil
  end

  -- every card a pairing system uses (asked once per open; nil while Character Reforged did not answer: asked again
  -- from Step, then the list is redrawn)
  function P.Uses()
    if P.uses ~= nil then
      return P.uses
    end
    local ok, list = pcall(funcLuaCommand, P.USES)
    if not ok or type(list) ~= "table" then
      P.uses_missed = true
      return nil
    end
    local map, n = {}, 0
    for _, e in pairs(list) do
      if type(e) == "table" and type(e[1]) == "number" and e[1] ~= 0 then
        map[e[1]] = {badge = type(e[2]) == "number" and e[2] or 0, partner = e[4] == true, system = tostring(e[5] or "?"),
          team_badge = type(e[6]) == "number" and e[6] or 0}
        n = n + 1
      end
    end
    P.uses = map
    P.Log("uses", n)
    return map
  end

  -- the badge of a card with a miximax or another pair, from any source: a stored pair (partner or base), else the
  -- move in his mix slot. Asked once per card while this bank is open
  function P.SystemBadge(card)
    if type(card) ~= "number" or card == 0 then
      return 0, 0
    end
    local known = P.badges[card]
    if known ~= nil then
      return known[1], known[2]
    end
    local uses = P.Uses()
    if uses == nil then
      return 0, 0
    end
    local use = uses[card]
    local badge, team_badge = 0, 0
    if use ~= nil then
      badge, team_badge = use.badge, use.team_badge
    else
      local ok, b, t = pcall(funcLuaCommand, P.MIX_BADGE, card)
      if ok then
        badge, team_badge = type(b) == "number" and b or 0, type(t) == "number" and t or 0
      end
    end
    P.badges[card] = {badge, team_badge}
    return badge, team_badge
  end

  -- paint list card `instance`: `badge` (sprite id, 0 = the retail icon) on the card's «in a team» icon, `team_badge`
  -- instead when he is also in a team (0 = the same badge). The retail card fill keeps the icon's visibility of a
  -- card without a badge
  function P.PaintCorner(layer, instance, card, badge, team_badge)
    if layer ~= P.CARD or type(instance) ~= "number" then
      return
    end
    if badge ~= 0 then
      local sprite = badge
      if team_badge ~= 0 and type(IsCharaInAnyTeam) == "function" and IsCharaInAnyTeam(card) then
        sprite = team_badge
      end
      local oks = pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.CARD, P.CORNER_SHEET, sprite, P.CORNER_SLOT, 0, instance)
      local okv = pcall(funcLuaMenuCommand, P.MESH_VISIBLE, P.CARD, P.CORNER_MESH, true, instance)
      P.cornered[instance] = true
      if not P.corner_logged[card] then
        P.corner_logged[card] = true
        P.Log("corner badge", string.format("%08X", card), instance, string.format("%08X", sprite), oks, okv)
      end
    elseif P.cornered[instance] then
      pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.CARD, P.CORNER_SHEET, P.CORNER_SLOT, P.CORNER_SLOT, 0, instance)
      P.cornered[instance] = nil
    end
  end

  function P.Word(e)
    if type(e.text) == "string" and e.text ~= "" then
      return e.text
    end
    if e.text_id ~= 0 then
      local ok, s = pcall(funcLuaCommand, P.TEXT_GET, e.text_id)
      if ok and type(s) == "string" and s ~= "" then
        return s
      end
    end
    return nil
  end

  -- the plate on list card `instance` (hidden for a free card, an empty instance or a system without a plate)
  function P.Paint(layer, instance, card)
    if layer ~= P.CARD or type(instance) ~= "number" then
      return
    end
    local e = P.Of(card)
    -- a «Crear …» partner bank shows the corner badge instead (graft character_reforged_board, B.PaintBadge)
    local picker = CharacterReforged_BankMoves ~= nil and CharacterReforged_BankMoves.created == true
    local shown = e ~= nil and e.sprite ~= 0 and not picker
    if shown then
      pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.BADGE, P.BADGE_SHEET, e.sprite, P.BADGE_SLOT, 0, instance)
      local word = P.Word(e)
      if word ~= nil then
        pcall(funcLuaMenuCommand, P.SET_TEXT, P.BADGE, P.BADGE_TEXT, word, instance)
      end
      pcall(funcLuaMenuCommand, P.TEXT_VISIBLE, P.BADGE, P.BADGE_TEXT, word ~= nil, instance)
      if not P.logged[card] then
        P.logged[card] = true
        P.Log("plate", string.format("%08X", card), string.format("%08X", e.base), instance)
      end
    end
    pcall(funcLuaMenuCommand, P.LAYER_VISIBLE, P.BADGE, instance, shown)
  end

  -- the bank's current list mode (retail local n18 through the framework's host; nil without it)
  function P.Mode()
    local ok, v = pcall(function()
      return VRFW_Host.hosts.chara_bank_menu.L.n18
    end)
    if ok then
      return v
    end
    return nil
  end

  if VRFW_Host ~= nil then
    for _, stem in ipairs(P.STEMS) do
      VRFW_Host.on(stem, "OnInit", {id = P.ID .. ".init", phase = "before", fn = function()
        P.Reset()
      end})
      -- a list drawn before Character Reforged answered: drawn again once the answer holds a locked card
      VRFW_Host.on(stem, "Step", {id = P.ID .. ".retry", phase = "after", fn = function()
        -- the uses asked before Character Reforged answered: read again, the list redrawn with the badges
        if P.uses == nil and P.uses_missed and P.Uses() ~= nil then
          P.uses_missed = false
          P.badges = {}
          local bank = CharacterReforged_BankMoves
          if bank ~= nil then
            bank.status, bank.refusal_logged = {}, {}
          end
          if UpdateList ~= nil then
            pcall(UpdateList)
          end
        end
        if P.map == nil and P.missed then
          local map = P.Map()
          if map ~= nil then
            P.missed = false
            if next(map) ~= nil and UpdateList ~= nil then
              pcall(UpdateList)
            end
          end
        end
      end})
      VRFW_Host.on(stem, "UpdateCharaCard", {id = P.ID .. ".plate", phase = "after", fn = function(r, layer, instance, card)
        P.Paint(layer, instance, card)
      end})
    end

    -- the player bank: the corner badge of each list card (the retail card refresh: page, scroll, sort, filter)
    VRFW_Host.on("chara_bank_menu", "UpdateCharaCard", {id = P.ID .. ".corner", phase = "after",
      fn = function(r, layer, instance, card)
        local badge, team_badge = P.SystemBadge(card)
        P.PaintCorner(layer, instance, card, badge, team_badge)
      end})

    -- the team dock's bank: the partner is disabled (greyed by the retail IsGrayOutBankChara through this)
    VRFW_Host.on("chara_bank_menu", "IsBankCharaEnabled", {id = P.ID .. ".disabled", phase = "around",
      fn = function(nxt, card, ...)
        if P.Mode() ~= P.QUICK_RETIRE_MODE and P.Of(card) ~= nil then
          return false
        end
        return nxt(card, ...)
      end})
    VRFW_Host.on("chara_bank_menu", "SearchEmptyFormationPosition", {id = P.ID .. ".no_slot", phase = "around",
      fn = function(nxt, card, ...)
        if P.Of(card) ~= nil then
          return -1, 255
        end
        return nxt(card, ...)
      end})
  end
end
